pub fn ftNs_AttackHi4_YoyoCheckNoObstruct<'a>(ctx: &'a Ctx, gobj: HSD_GObj<'a>) -> i32 {
    let __frame = ctx.stack_frame(0x38);
    let sp20: Vec<'a> = frame_at(ctx, &__frame, 0x18);
    let sp14: Vec<'a> = frame_at(ctx, &__frame, 0xc);
    let mut gobj = gobj;
    let mut ECB_MUL_Y: f64 = 0.0;
    let mut ECB_X: f64 = 0.0;
    let mut fp: Fighter<'a> = null(ctx);
    fp = (Handle::cast::<Fighter<'a>>(inl_HSD_GObjGetUserData(ctx, gobj)));
    ECB_X = 0.0;
    ECB_MUL_Y = 0.5;
    sp20.set_x(ECB_X);
    sp20.set_y(fp::fmuls(
        ECB_MUL_Y,
        (fp::fadds(
            (fp).coll_data().ecb().top().y(),
            (fp).coll_data().ecb().bottom().y(),
        )),
    ));
    sp20.set_z(ECB_X);
    sp20.set_x(fp::fadds(sp20.x(), (fp).cur_pos().x()));
    sp20.set_y(fp::fadds(sp20.y(), (fp).cur_pos().y()));
    sp20.set_z(fp::fadds(sp20.z(), (fp).cur_pos().z()));
    Handle::copy_from(sp14, (fp).u().ns().yoyo_hitbox_pos());
    if !(fns::ftNs_AttackHi4_YoyoCheckEnvColl(ctx, gobj, sp20, sp14, ECB_MUL_Y) != 0) {
        Handle::copy_from(sp14, (fp).u().ns().yoyo_hitbox_pos());
        Handle::copy_from(sp20, sp14);
        sp20.set_y(fp::fadds(sp20.y(), (fp).x34_scale().y()));
        sp14.set_y(fp::fmadds(fp::fneg(1.0), (fp).x34_scale().y(), sp14.y()));
        if (fns::ftNs_AttackHi4_YoyoCheckEnvColl(ctx, gobj, sp20, sp14, 1.5) & 0x8000_i32) != 0_i32
        {
            return 1_i32;
        }
    }
    return 0_i32;
}

