pub fn ftNs_AttackHi4_IASA<'a>(ctx: &'a Ctx, gobj: HSD_GObj<'a>) {
    let __frame = ctx.stack_frame(0x8);
    let mut gobj = gobj;
    let mut fp: Fighter<'a> =
        (Handle::cast::<Fighter<'a>>(inl_HSD_GObjGetUserData_unfused(ctx, gobj)));
    if ((fp).input().held_buttons().at(0_i32).get() & ((shl_i32(1_i32, (8_i32 as u32))) as u32))
        == (0_i32 as u32)
    {
        (fp).mv().ns().attackhi4().set_isChargeDisable(1_i32);
    }
    if ((fp).allow_interrupt() as i32) != 0_i32 {
        fns::ftCo_Wait_IASA(ctx, gobj);
    }
}

